const visual = {
  prepare: function (input) { return []; },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 400;
    var H = (input && input.viewport && input.viewport.heightDu) || 400;
    var cols = 4;
    var rows = 4;
    var margin = Math.min(W, H) * 0.08;
    var avail = Math.min(W - 2 * margin, H - 2 * margin);
    var cell = avail / Math.max(cols, rows);
    var gw = cell * cols;
    var gh = cell * rows;
    var x0 = (W - gw) / 2;
    var y0 = (H - gh) / 2;
    var cmds = [];
    var i, x, y;
    for (i = 0; i <= cols; i++) {
      x = x0 + i * cell;
      cmds = cmds.concat(visualSdk.polyline([[x, y0], [x, y0 + gh]]));
    }
    for (i = 0; i <= rows; i++) {
      y = y0 + i * cell;
      cmds = cmds.concat(visualSdk.polyline([[x0, y], [x0 + gw, y]]));
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid-4x4',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'grid', commands: cmds }],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'grid', fill: 'none', stroke: { width: 1.5 } }
        ]
      }
    };
  }
};
